import re

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Message


# Headers generated by PostgreSQL Course Search.
HEADER_RE = re.compile(
    r"(?m)^\[\d+;\s*document_id=(\d+);"
    r"\s*chunk_id=(\d+);"
    r"\s*cosine_distance=[^\]]+\]"
)

# The marker must be a separate line at the end of the answer.
MARKER_RE = re.compile(
    r"(?im)^USED_SOURCES\s*:\s*([^\r\n]*)\s*$"
)

PAIR_RE = re.compile(r"^(\d+)\s*:\s*(\d+)$")


def extract_text(value) -> str:
    """Extract plain text from a Langflow input."""
    if isinstance(value, (list, tuple)):
        value = value[-1] if value else ""

    if hasattr(value, "text"):
        value = value.text
    elif hasattr(value, "data") and isinstance(value.data, dict):
        data = value.data
        value = data.get("text") or data.get("content") or ""
    elif isinstance(value, dict):
        value = value.get("text") or value.get("content") or ""

    return str(value or "").strip()


def format_document(document_id: str) -> str:
    """
    Format one document for the student.

    When trusted title/link metadata becomes available, pass it to this
    component and update this function. IDs alone do not provide titles.
    """
    return f"Документ №{document_id}"


class SourcesFormatter(Component):
    display_name = "Sources Formatter"
    description = (
        "Validate the agent's cited chunk IDs against retrieved context "
        "and format document references."
    )
    icon = "prompts"
    name = "SourcesFormatter"

    inputs = [
        MessageTextInput(
            name="answer",
            display_name="Agent Answer",
            info="Agent response ending with a USED_SOURCES line.",
            required=True,
        ),
        MessageTextInput(
            name="context",
            display_name="Retrieved Context",
            info="Accepted chunks passed to the agent.",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="response",
            display_name="Response",
            method="build_response",
            types=["Message"],
            selected="Message",
        ),
    ]

    def build_response(self) -> Message:
        answer = extract_text(self.answer)
        context = extract_text(self.context)

        if not answer:
            raise ValueError("The agent response is empty.")

        allowed_pairs = {
            (match.group(1), match.group(2))
            for match in HEADER_RE.finditer(context)
        }

        markers = list(MARKER_RE.finditer(answer))

        # Remove marker lines even if the model placed them incorrectly.
        clean_answer = MARKER_RE.sub("", answer).strip()

        if not clean_answer:
            raise ValueError("The agent response contains no answer text.")

        if len(markers) != 1:
            self.status = "MISSING_OR_MULTIPLE_SOURCE_MARKERS"
            return Message(
                text=(
                    f"{clean_answer}\n\n"
                    "Не удалось проверить источники этого ответа."
                )
            )

        marker = markers[0]

        # A valid marker must be the final non-whitespace content.
        if answer[marker.end():].strip():
            self.status = "SOURCE_MARKER_NOT_LAST"
            return Message(
                text=(
                    f"{clean_answer}\n\n"
                    "Не удалось проверить источники этого ответа."
                )
            )

        raw_sources = marker.group(1).strip()

        if raw_sources.lower() == "none":
            self.status = "NO_SOURCES_DECLARED"
            return Message(text=clean_answer)

        if not raw_sources:
            self.status = "EMPTY_SOURCE_MARKER"
            return Message(
                text=(
                    f"{clean_answer}\n\n"
                    "Не удалось проверить источники этого ответа."
                )
            )

        valid_pairs = []
        seen_pairs = set()
        invalid_found = False

        for item in raw_sources.split(","):
            match = PAIR_RE.fullmatch(item.strip())

            if not match:
                invalid_found = True
                continue

            pair = (match.group(1), match.group(2))

            if pair not in allowed_pairs:
                invalid_found = True
                continue

            if pair not in seen_pairs:
                seen_pairs.add(pair)
                valid_pairs.append(pair)

        if not valid_pairs:
            self.status = "NO_VALID_SOURCE_IDS"
            return Message(
                text=(
                    f"{clean_answer}\n\n"
                    "Не удалось проверить источники этого ответа."
                )
            )

        document_ids = []
        seen_documents = set()

        for document_id, _chunk_id in valid_pairs:
            if document_id not in seen_documents:
                seen_documents.add(document_id)
                document_ids.append(document_id)

        sources = "\n".join(
            f"- {format_document(document_id)}"
            for document_id in document_ids
        )

        result = f"{clean_answer}\n\nИсточники:\n{sources}"

        if invalid_found:
            result += (
                "\n\nНекоторые указанные моделью ссылки "
                "не удалось проверить."
            )
            self.status = "PARTIALLY_VALID_SOURCES"
        else:
            self.status = "VALID_SOURCE_IDS"

        return Message(text=result)
